insert into public.knowledge_base (entity_type, entity_id, title, content, url, version, is_published, content_hash)
values
  ('faq', '00000000-0000-4000-8000-000000000200', 'Accueil / Home (vue d''ensemble de la ville)', 'Page / : vue d''ensemble de la ville avec indicateurs, services, signalements, projets les plus soutenus, les plus utilisés, transports et raccourcis. City overview page with KPIs, services, reports, projects, most used items, transport and shortcuts.', '/', 1, true, 'dcf9a6bfa4ab4c23f6523fb83fa9032f'),
  ('faq', '00000000-0000-4000-8000-000000000201', 'Page Welcome', 'Page /welcome : page d''accueil de présentation de Nova Terra avec barre de navigation Home et Welcome. Presentation landing page.', '/welcome', 1, true, 'c73818336207b1d9ea82dc83d6162e71'),
  ('faq', '00000000-0000-4000-8000-000000000202', 'Se connecter / Log in', 'Page /connexion : connexion avec e-mail et mot de passe. Un lien permet de récupérer un mot de passe oublié (/mot-de-passe-oublie). Les administrateurs utilisent /admin/connexion. Log in with email and password.', '/connexion', 1, true, '9709975dce3a7bfd70db4dacdbeca3a0'),
  ('faq', '00000000-0000-4000-8000-000000000203', 'Créer un compte / Sign up', 'Page /inscription : création d''un compte citoyen. Après l''inscription, vérifiez votre identité (CIN) dans /app/verification pour pouvoir voter et commenter. Create a citizen account, then verify identity to vote and comment.', '/inscription', 1, true, 'd4a790ac56ba2df1814e0ee2a584ed3f'),
  ('faq', '00000000-0000-4000-8000-000000000204', 'Mot de passe oublié / Reset password', 'Page /mot-de-passe-oublie : recevez un e-mail pour réinitialiser votre mot de passe, puis choisissez-en un nouveau sur /nouveau-mot-de-passe.', '/mot-de-passe-oublie', 1, true, '42d4b1a1815af7e0b1e8b1cb0be21de9'),
  ('faq', '00000000-0000-4000-8000-000000000205', 'Services de la ville / City services', 'Page /services : liste des services publics avec statut, horaires, note moyenne. Cliquez un service pour voir /services/:slug : démarches, documents requis, contacts, calendrier de rendez-vous, avis et commentaires. Dans votre espace utilisez /app/services.', '/services', 1, true, '7434288ed80ed71b63772ae1a1d258f9'),
  ('faq', '00000000-0000-4000-8000-000000000206', 'Avis et commentaires sur un service ou un équipement / Reviews', 'Pour noter ou commenter un service ou un équipement : ouvrez /app/services (Services et avis), choisissez un service, puis utilisez la section Avis en bas de la fiche. Il faut un compte connecté et vérifié. Rate or comment a service or facility from its detail page.', '/app/services', 1, true, '067a699aeb9b40874ecdf0358a57bc34'),
  ('faq', '00000000-0000-4000-8000-000000000207', 'Projets de la ville et votes / City projects & voting', 'Pour voter pour un projet ou le commenter : ouvrez /app/projects (Projets et votes) dans votre espace, ou /projects en public. Il faut un compte vérifié. Vote and comment on city projects.', '/app/projects', 1, true, 'cc0b0a72edb8abd05ee0e1d0abc5c36a'),
  ('faq', '00000000-0000-4000-8000-000000000208', 'Actualités / News', 'Page /news : actualités publiées par les services. /news/:slug : article détaillé avec commentaires.', '/news', 1, true, 'd3c2656b111a5f5f3a91d3356ff08d87'),
  ('faq', '00000000-0000-4000-8000-000000000209', 'Carte de la ville / Map', 'Page /map : carte interactive de la ville avec secteurs, bâtiments, services et dangers.', '/map', 1, true, '2104c6fe4a39ba7d22196a860236f883'),
  ('faq', '00000000-0000-4000-8000-000000000210', 'Dangers et alertes / Dangers & alerts', 'Page /dangers : alertes et dangers actifs ou archivés. /dangers/:slug : détail d''une alerte. En cas d''urgence appelez les numéros d''urgence.', '/dangers', 1, true, '22e076a35f0712711cd1162880118727'),
  ('faq', '00000000-0000-4000-8000-000000000211', 'Guide et FAQ', 'Pages /guide et /faq : aide à l''utilisation de l''application et questions fréquentes.', '/guide', 1, true, '92a0b44b9979830fb3c7eacaad83ea70'),
  ('faq', '00000000-0000-4000-8000-000000000212', 'API développeurs / Developer API', 'Page /developers : catalogue de l''API publique et des fonctions (chat Gemini, chat vocal, etc.) pour les développeurs.', '/developers', 1, true, '9c41d2e350b9beb3ab4cdb0897da797b'),
  ('faq', '00000000-0000-4000-8000-000000000213', 'Mon espace : tableau de bord / My space dashboard', 'Page /app : tableau de bord du citoyen avec résumé de vos demandes, signalements et notifications. Menu latéral Mon espace.', '/app', 1, true, 'effeeec314118239e6f398644c6c0ab0'),
  ('faq', '00000000-0000-4000-8000-000000000214', 'Mes demandes / My requests', 'Page /app/requests : créez et suivez vos demandes auprès des services (numéro de suivi, statut, messages). Vous pouvez aussi demander à l''assistant de créer une demande ; il demande confirmation avant.', '/app/requests', 1, true, '708e910e0dd1fad667ca3a45ed2199a4'),
  ('faq', '00000000-0000-4000-8000-000000000215', 'Mes signalements / My reports', 'Page /app/reports : signalez un problème (voirie, éclairage, déchets...) et suivez son traitement. L''assistant peut préparer un signalement avec confirmation.', '/app/reports', 1, true, '1d0028dbe0a7273c506e48016950ee05'),
  ('faq', '00000000-0000-4000-8000-000000000216', 'Appeler un conseiller / Call an agent', 'Page /app/support : demandez à parler à un conseiller (appel). Call an agent.', '/app/support', 1, true, '48d0327a7b274f0dbcff8dbcf05e19cb'),
  ('faq', '00000000-0000-4000-8000-000000000217', 'Vérification d''identité / Identity verification', 'Page /app/verification : envoyez votre CIN pour vérifier votre identité. Un compte vérifié est nécessaire pour voter, commenter et noter.', '/app/verification', 1, true, '756769c6c75a82d530713c63c74df8f1'),
  ('faq', '00000000-0000-4000-8000-000000000218', 'Accessibilité et thème / Accessibility', 'Page /app/accessibility : choisissez le thème (minimaliste ou Nova Terra), taille du texte, contraste, animations réduites, lecture à voix haute.', '/app/accessibility', 1, true, 'eaa9796f36129b051ae65257edb4c0c1'),
  ('faq', '00000000-0000-4000-8000-000000000219', 'Lettres d''information / Newsletters', 'Page /app/newsletter : abonnez-vous ou désabonnez-vous des lettres d''information.', '/app/newsletter', 1, true, '74dfed12cf67f34e0383058a9900274a'),
  ('faq', '00000000-0000-4000-8000-000000000220', 'Réputation et votes sur les utilisateurs / Reputation', 'Page /app/reputation : classement et réputation des utilisateurs. Ouvrez un profil (/app/reputation/:profileId) pour voter pour un utilisateur. Vote for a user from their profile.', '/app/reputation', 1, true, 'c6faa4690da89df7f54e7f76f8b099f2'),
  ('faq', '00000000-0000-4000-8000-000000000221', 'Paramètres / Settings', 'Page /app/parametres : profil, langue, mot de passe, sécurité, alertes de connexion, suppression du compte.', '/app/parametres', 1, true, 'f4830073e8ea708f5c0377b61154a714'),
  ('faq', '00000000-0000-4000-8000-000000000222', 'Assistant virtuel / Chatbot', 'Bouton flottant d''assistant : posez vos questions sur la ville et l''application (réponses Gemini à partir des données publiées, avec sources), dictée vocale, lecture à voix haute. Limite de 20 messages IA par jour. L''assistant ne crée rien sans votre confirmation.', '/?assistant=open', 1, true, '792dbac047e515a617548795b64e0443'),
  ('faq', '00000000-0000-4000-8000-000000000223', 'Espace agent : tableau de bord / Agent workspace', 'Pour les agents et administrateurs de service : /agent/requests (demandes), /agent/reports (signalements), /agent/dangers (alertes), /agent/analytics (analyses), /agent/calls (appels), /agent/news (actualités du service), /agent/services (mes services), /agent/projects (votes sur les projets), /agent/team (équipe), /agent/sync (synchronisation API).', '/agent', 1, true, 'c922ed8414d97b8756b193b5d898e57d'),
  ('faq', '00000000-0000-4000-8000-000000000224', 'Administration / Admin', 'Pour les administrateurs : /admin/users (utilisateurs et rôles), /admin/verifications (vérifications CIN), /admin/services, /admin/projects (projets de la ville), /admin/map (éditeur de carte), /admin/news (modération), /admin/dangers, /admin/reports, /admin/analytics, /admin/ai-content (contenu IA), /admin/audit (journal d''audit). Connexion admin : /admin/connexion.', '/admin', 1, true, '16df3140264a728ba009c222cb1a6120'),
  ('faq', '00000000-0000-4000-8000-000000000225', 'Barre de navigation et menu / Navigation', 'L''en-tête public contient les liens principaux, la langue (FR/EN), l''aide, le mode clair/sombre, le menu utilisateur (Mon espace, Paramètres, Quitter) et le bouton Espace admin pour les administrateurs. Dans l''espace connecté, la barre latérale regroupe Mon espace, Espace agent, Administration et La ville.', '/', 1, true, '1957f341d0e4f22484942932d18c4de7'),
  ('faq', '00000000-0000-4000-8000-000000000226', 'Rôles / Roles', 'Rôles : citoyen (compte vérifié pour voter et commenter), agent, administrateur de service, administrateur général. Chaque rôle voit son menu dans la barre latérale.', '/app', 1, true, '07c8176b4320d07e8c7acd18b94babf0')
